from scipy.optimize import least_squares
y=dP_dt
def build(p,deg,tb):
    g=1-np.exp(-p[0]*t**p[1])
    T=[np.ones_like(t)]
    if tb>=1: T.append(g)
    if tb>=2: T.append(t)
    if tb>=3: T.append(t**2)
    if tb>=4: T.append(g*t)
    cols=[]
    for Tk in T:
        for k in range(deg+1):
            cols.append(Tk*P**k)
    return np.column_stack(cols)
